// „ეკლესია-მონასტრები“ (pages/ChurchesPage.tsx): every church and monastery of Georgia outside the occupied lands —
// 3 407 from „ეკლესიის ტერიტორიულობა“ (Indigo, toc.ge, 2021) — with photos and Wikipedia links from Wikidata where
// they could be joined. `churches.json` is generated by scripts/churches/build.py — never edit it by hand.

/** [id, name, municipality №, village or address, lat (0 = unknown), lng, kind, built, under construction, note, Commons photo
 *  file, ka.wikipedia title, Wikidata description] */
export type ChurchRow = [string, string, number, string, number, number, ChurchKind, string, 0 | 1, string, string, string, string];
export type ChurchKind = 'c' | 'm' | 'x';
interface ChurchFile { updated: string; munis: [string, string][]; items: ChurchRow[] }

export interface Church {
  id: string;
  name: string;
  region: string;
  /** „საჩხერის მუნიციპალიტეტი“, „ვაკის რაიონი“, „ქ. ქუთაისი“ */
  muni: string;
  place: string;
  lat: number;
  lng: number;
  /** a place on the map is known */
  located: boolean;
  kind: ChurchKind;
  built: string;
  building: boolean;
  note: string;
  photo: string;
  wiki: string;
  desc: string;
  /** lowercased name + place + municipality, for the search */
  text: string;
}
export interface ChurchData { updated: string; list: Church[]; byId: Map<string, Church> }

let loading: Promise<ChurchData> | null = null;
export const loadChurches = () =>
  (loading ??= import('./churches.json').then(m => toData(m.default as unknown as ChurchFile)).catch(e => { loading = null; throw e; }));

const toData = (f: ChurchFile): ChurchData => {
  const list = f.items.map(r => {
    const [muni, region] = f.munis[r[2]];
    return {
      id: r[0], name: r[1], region, muni, place: r[3], lat: r[4], lng: r[5], located: r[4] !== 0, kind: r[6], built: r[7],
      building: r[8] === 1, note: r[9], photo: r[10], wiki: r[11], desc: r[12],
      text: `${r[1]} ${r[3]} ${muni}`.toLowerCase(),
    };
  });
  return { updated: f.updated, list, byId: new Map(list.map(c => [c.id, c])) };
};

export const KIND_LABEL: Record<ChurchKind, string> = { c: 'ეკლესია', m: 'მონასტერი', x: 'არ მოქმედებს' };

/** where it is, in words: „სოფ. ზედა გორდი · ხონის მუნიციპალიტეტი“; a Tbilisi district says Tbilisi */
export const whereOf = (c: Church) => {
  const muni = c.muni.endsWith('რაიონი') ? `თბილისი, ${c.muni}` : c.muni;
  if (!c.place || c.muni.includes(c.place) || muni.includes(c.place)) return muni;
  return `${c.place} · ${muni}`;
};

export const photoUrl = (file: string, width = 640) =>
  `https://commons.wikimedia.org/wiki/Special:FilePath/${encodeURIComponent(file)}?width=${width}`;
export const photoPage = (file: string) => `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(file.replace(/ /g, '_'))}`;
export const wikiUrl = (title: string) => `https://ka.wikipedia.org/wiki/${encodeURIComponent(title.replace(/ /g, '_'))}`;
/** Google Maps: the way there from where the phone is (the app on a phone, the site on a computer) */
export const routeUrl = (c: Church) => `https://www.google.com/maps/dir/?api=1&destination=${c.lat},${c.lng}`;
/** Google Maps: the place itself, with its photos and reviews when Google knows it */
export const placeUrl = (c: Church) => `https://www.google.com/maps/search/?api=1&query=${c.lat},${c.lng}`;

/** metres between two points */
export const distanceM = (lat1: number, lng1: number, lat2: number, lng2: number) => {
  const r = Math.PI / 180;
  const h = Math.sin(((lat2 - lat1) * r) / 2) ** 2 + Math.cos(lat1 * r) * Math.cos(lat2 * r) * Math.sin(((lng2 - lng1) * r) / 2) ** 2;
  return 2 * 6371000 * Math.asin(Math.min(1, Math.sqrt(h)));
};

/** the nearest churches with a known place, nearest first */
export const nearest = (list: Church[], lat: number, lng: number, count = 30) =>
  list
    .filter(c => c.located)
    .map(c => ({ church: c, m: distanceM(lat, lng, c.lat, c.lng) }))
    .sort((a, b) => a.m - b.m)
    .slice(0, count);

export const distanceText = (m: number) => (m < 950 ? `${Math.max(50, Math.round(m / 50) * 50)} მ` : `${(m / 1000).toFixed(m < 9500 ? 1 : 0)} კმ`);

/** every word typed must be found (a word's start is enough): „ბოდბე ნინო“ */
export const matchChurch = (c: Church, query: string) => {
  const words = query.toLowerCase().split(/\s+/).filter(Boolean);
  return words.every(w => c.text.includes(w));
};

export type KindFilter = 'all' | 'active' | 'm' | 'x';
export const KIND_FILTERS: { id: KindFilter; label: string }[] = [
  { id: 'all', label: 'ყველა' },
  { id: 'active', label: 'მოქმედი' },
  { id: 'm', label: 'მონასტრები' },
  { id: 'x', label: 'არ მოქმედებს' },
];
export const passesKind = (c: Church, f: KindFilter) =>
  f === 'all' || (f === 'active' ? c.kind !== 'x' : c.kind === f);
